  3	/// SVT-AV1 v4.2.0, the `av1` row's encoder (spec §11 CX-2, CX-4, CX-12): one handle per
  4	/// export, configured once, fed BT.709 video-range I420 pictures and drained of packets.
  5	///
  6	/// **Owned by one serial queue.** `ExportEncodePump`'s encode queue makes every call after
  7	/// `init` — `send`, `sendEndOfStream`, `nextPacket` and the `deinit` — so the handle is
  8	/// never touched from two threads; SVT runs its own worker threads behind it.
  9	///
 10	/// **The configuration** (CX-12 (2), (3); CX-13): the sheet's speed as SVT's preset (8, 6 or
 11	/// 4), capped CRF — a constant quality matched to HEVC's at the cap, which is the settings'
 12	/// rate or HEVC's 0.07 bits per pixel per frame — a closed GOP (`SVT_AV1_KF_REFRESH`) with a
 13	/// keyframe at least every 2 s, 8-bit 4:2:0, and BT.709 primaries, transfer and matrix in
 14	/// video range written into the sequence header.
 15	final class SVTAV1Encoder {
 16	    /// One packet as SVT answered it: its bytes (temporal delimiters still in), the `pts` the
 17	    /// picture was sent with, and whether it is the last.
 18	    struct Packet {
 19	        let data: Data
 20	        let pts: Int64
 21	        let isLast: Bool
 22	    }
 23	
 24	    /// The sequence header OBU (`svt_av1_enc_stream_header`), the `av1C` record's source.
 25	    let sequenceHeader: Data
 26	
 27	    private var handle: UnsafeMutablePointer<EbComponentType>?
 28	    /// Set after the first failed call: nothing more is asked of the handle but its teardown.
 29	    private var broken = false
 30	
 31	    init(width: Int, height: Int, fps: Fps, bitsPerSecond: Int, speed: EncoderSpeed) throws {
 32	        _ = Self.installLogCallback
 33	        var config = EbSvtAv1EncConfiguration()
 34	        var opened: UnsafeMutablePointer<EbComponentType>?
 35	        try Self.check(svt_av1_enc_init_handle(&opened, &config), "svt_av1_enc_init_handle")
 36	        guard let opened else {
 37	            throw Exporter.ExportError.failed("SVT-AV1 could not start: no handle was made.")
 38	        }
 39	        config.enc_mode = speed.svtPreset
 40	        config.source_width = UInt32(clamping: width)
 41	        config.source_height = UInt32(clamping: height)
 42	        config.frame_rate_numerator = UInt32(clamping: fps.num)
 43	        config.frame_rate_denominator = UInt32(clamping: fps.den)
 44	        config.encoder_bit_depth = 8
 45	        config.encoder_color_format = EB_YUV420
 46	        // Capped CRF (CX-13): what SVT's own `--crf` sets, and the cap as `max_bit_rate`.
 47	        let cap = min(max(1, bitsPerSecond), Self.maxCap)
 48	        config.rate_control_mode = UInt8(SVT_AV1_RC_MODE_CQP_OR_CRF.rawValue)
 49	        config.aq_mode = 2
 50	        config.qp = Self.crf(speed: speed, bitsPerPixel: Double(cap)
 51	            / (Double(max(1, width * height)) * (fps.double > 0 ? fps.double : 30)))
 52	        config.max_bit_rate = UInt32(cap)
 53	        // SVT-AV1 v4.2.0's own default (`EbSvtAv1Enc.h`, `enc_settings.c`): a soft cap that
 54	        // hard footage may exceed, the owner's "quality first" (CX-13 (1)).
 55	        config.mbr_over_shoot_pct = 50
 56	        // Closed GOP, and a keyframe at least every 2 s: the period is ⌊2·fps⌋ frames.
 57	        config.intra_refresh_type = SVT_AV1_KF_REFRESH
 58	        let perSecond = fps.den > 0 ? Double(fps.num) / Double(fps.den) : 30
 59	        config.intra_period_length = Int32(max(1, (2 * perSecond).rounded(.down))) - 1
 60	        config.color_primaries = EB_CICP_CP_BT_709
 61	        config.transfer_characteristics = EB_CICP_TC_BT_709
 62	        config.matrix_coefficients = EB_CICP_MC_BT_709
 63	        config.color_range = EB_CR_STUDIO_RANGE
 64	        do {
 65	            sequenceHeader = try Self.start(opened, &config)
 66	        } catch {
 67	            _ = svt_av1_enc_deinit(opened)
 68	            _ = svt_av1_enc_deinit_handle(opened)
 69	            throw error
 70	        }
 71	        handle = opened
 72	    }
 73	
 74	    /// Configures and starts the handle, answering its sequence header.
 75	    private static func start(
 76	        _ handle: UnsafeMutablePointer<EbComponentType>, _ config: inout EbSvtAv1EncConfiguration
 77	    ) throws -> Data {
 78	        try check(svt_av1_enc_set_parameter(handle, &config), "svt_av1_enc_set_parameter")
 79	        try check(svt_av1_enc_init(handle), "svt_av1_enc_init")
 80	        var header: UnsafeMutablePointer<EbBufferHeaderType>?
 81	        try check(svt_av1_enc_stream_header(handle, &header), "svt_av1_enc_stream_header")
 82	        guard let header, let bytes = header.pointee.p_buffer else {
 83	            throw Exporter.ExportError.failed("SVT-AV1 could not start: it wrote no stream header.")
 84	        }
 85	        defer { _ = svt_av1_enc_stream_header_release(header) }
 86	        return Data(bytes: bytes, count: Int(header.pointee.n_filled_len))
 87	    }
 88	
 89	    @available(*, unavailable) required init?(coder: NSCoder) {
 90	        fatalError("SVTAV1Encoder does not support NSCoder")
 91	    }
 92	
 93	    deinit {
 94	        guard let handle else { return }
 95	        _ = svt_av1_enc_deinit(handle)
 96	        _ = svt_av1_enc_deinit_handle(handle)
 97	    }
 98	
 99	    /// Sends one picture; SVT copies its planes, so `frame` may be reused once this returns.
100	    func send(_ frame: I420Frame, index: Int64) throws {
101	        guard let handle, !broken else { throw Self.stopped }
102	        let base = frame.buffer.contents().assumingMemoryBound(to: UInt8.self)
103	        var planes = EbSvtIOFormat(
104	            luma: base, cb: base + frame.cbOffset, cr: base + frame.crOffset,
105	            y_stride: UInt32(frame.lumaStride), cr_stride: UInt32(frame.chromaStride),
106	            cb_stride: UInt32(frame.chromaStride))
107	        try withUnsafeMutablePointer(to: &planes) { io in
108	            var picture = EbBufferHeaderType()
109	            picture.size = UInt32(MemoryLayout<EbBufferHeaderType>.size)
110	            picture.p_buffer = UnsafeMutableRawPointer(io).assumingMemoryBound(to: UInt8.self)
111	            let chroma = frame.chromaStride * ((frame.height + 1) / 2)
112	            picture.n_filled_len = UInt32(frame.lumaStride * frame.height + 2 * chroma)
113	            picture.n_alloc_len = picture.n_filled_len
114	            picture.pts = index
115	            picture.pic_type = EB_AV1_INVALID_PICTURE
116	            try record(svt_av1_enc_send_picture(handle, &picture), "svt_av1_enc_send_picture")
117	        }
118	    }
119	
120	    /// Tells SVT no picture follows, so `nextPacket(wait: true)` drains to the last packet.
121	    func sendEndOfStream() throws {
122	        guard let handle, !broken else { throw Self.stopped }
123	        var end = EbBufferHeaderType()
124	        end.size = UInt32(MemoryLayout<EbBufferHeaderType>.size)
125	        end.flags = UInt32(EB_BUFFERFLAG_EOS)
126	        end.pic_type = EB_AV1_INVALID_PICTURE
127	        try record(svt_av1_enc_send_picture(handle, &end), "svt_av1_enc_send_picture")
128	    }
129	
130	    /// The next packet: nil when none is ready (`wait` false); `wait` true blocks until one
131	    /// is, which is only asked after `sendEndOfStream`.
132	    func nextPacket(wait: Bool) throws -> Packet? {
133	        guard let handle, !broken else { throw Self.stopped }
134	        var out: UnsafeMutablePointer<EbBufferHeaderType>?
135	        let answer = svt_av1_enc_get_packet(handle, &out, wait ? 1 : 0)
136	        if answer == EB_NoErrorEmptyQueue { return nil }
137	        try record(answer, "svt_av1_enc_get_packet")
138	        guard let header = out?.pointee else { return nil }
139	        defer { svt_av1_enc_release_out_buffer(&out) }
140	        let length = Int(header.n_filled_len)
141	        let data = header.p_buffer.map { Data(bytes: $0, count: length) } ?? Data()
142	        return Packet(
143	            data: data, pts: header.pts, isLast: header.flags & UInt32(EB_BUFFERFLAG_EOS) != 0)
144	    }
145	
146	    // MARK: - The rate (CX-13)
147	
148	    /// SVT-AV1's largest `max_bit_rate`, 100,000 kb/s.
149	    private static let maxCap = 100_000_000
150	
151	    /// CX-13 (3)'s calibration: at each cap in bits per pixel per frame (the Quality tiers'
152	    /// and "Format default"'s at 1080p30), the highest CRF at which each speed reached VMAF
153	    /// ≥ HEVC's at that rate on every calibration clip — the spike's three 8-bit clips and
154	    /// the owner's 55 s clip through this app — Faster, Balanced, Smaller file.
155	    private static let calibration: [(bitsPerPixel: Double, crf: [EncoderSpeed: Double])] = [
156	        (0.0386, [.faster: 40, .balanced: 36, .smaller: 36]),
157	        (0.0579, [.faster: 28, .balanced: 30, .smaller: 30]),
158	        (0.0700, [.faster: 24, .balanced: 26, .smaller: 26]),
159	        (0.0772, [.faster: 22, .balanced: 24, .smaller: 24]),
160	        (0.1157, [.faster: 14, .balanced: 16, .smaller: 16]),
161	    ]
162	
163	    /// The CRF for `speed` at a cap of `bitsPerPixel`: linear between the calibrated points,
164	    /// rounded down, and the end point's beyond either end.
165	    static func crf(speed: EncoderSpeed, bitsPerPixel: Double) -> UInt32 {
166	        let points = calibration.map { ($0.bitsPerPixel, $0.crf[speed] ?? 32) }
167	        guard let first = points.first, let last = points.last else { return 32 }
168	        if !(bitsPerPixel > first.0) { return UInt32(first.1) }
169	        if bitsPerPixel >= last.0 { return UInt32(last.1) }
170	        for (low, high) in zip(points, points.dropFirst()) where bitsPerPixel < high.0 {
171	            let share = (bitsPerPixel - low.0) / (high.0 - low.0)
172	            return UInt32((low.1 + share * (high.1 - low.1)).rounded(.down))
173	        }
174	        return UInt32(last.1)
175	    }
176	
177	    // MARK: - Errors and the log
178	
179	    private static let stopped = Exporter.ExportError.failed(
180	        "SVT-AV1 stopped after an earlier error.")
181	
182	    private func record(_ answer: EbErrorType, _ step: String) throws {
183	        guard answer != EB_ErrorNone else { return }
184	        broken = true
185	        throw Exporter.ExportError.failed("SVT-AV1 failed: \(step) answered \(Self.hex(answer)).")
186	    }
187	
188	    private static func check(_ answer: EbErrorType, _ step: String) throws {
189	        guard answer != EB_ErrorNone else { return }
190	        throw Exporter.ExportError.failed(
191	            "SVT-AV1 could not start: \(step) answered \(hex(answer)).")
192	    }
193	
194	    private static func hex(_ answer: EbErrorType) -> String {
195	        "0x" + String(UInt32(bitPattern: answer.rawValue), radix: 16)
196	    }
197	
198	    /// SVT's log through its callback (spec §11 CX-12 (6)), installed once per process before
199	    /// the first `svt_av1_enc_init_handle`, which finalises the library's logging: info and
200	    /// debug dropped, warnings and errors as `SVT-AV1: …` lines in the system log.
201	    private static let installLogCallback: Void = {
202	        svt_av1_set_log_callback({ _, level, _, format, arguments in
203	            guard level.rawValue >= 0, level.rawValue <= SVT_AV1_LOG_WARN.rawValue, let format,
204	                let arguments
205	            else { return }
206	            var text = [CChar](repeating: 0, count: 1024)
207	            _ = vsnprintf(&text, text.count, format, arguments)
208	            let line = String(cString: text).trimmingCharacters(in: .whitespacesAndNewlines)
209	            NSLog("SVT-AV1: %@", line)
210	        }, nil)
211	    }()
212	}
  1	//
  2	//  ExportI420.metal — the `av1` row's frames for SVT-AV1 (spec §11 CX-12 (5)):
  3	//  a compositor frame (64RGBAHalf, SDR BT.709, premultiplied) converted to
  4	//  BT.709 video-range 8-bit I420 in three planes of one buffer. Owned by
  5	//  `app/Sources/ExportI420.swift`, which scales the frame to the export size
  6	//  first when it is not the canvas.
  7	//
  8	//  One thread per 2 × 2 block: it writes the block's four luma samples and
  9	//  one Cb and one Cr, the mean of the four pixels' (a 2 × 2 box, the chroma
 10	//  siting SVT's sequence header leaves unspecified). RGB is clamped to 0…1 and
 11	//  read as it is, premultiplied, so a transparent canvas lands on black as it
 12	//  does through VideoToolbox on `h264`.
 13	//
 14	//  Y′ = 0.2126 R + 0.7152 G + 0.0722 B; Y = round(16 + 219 Y′);
 15	//  Cb = round(128 + 224 (B − Y′) / 1.8556); Cr = round(128 + 224 (R − Y′) / 1.5748).
 16	//
 17	
 18	#include <metal_stdlib>
 19	using namespace metal;
 20	
 21	/// Mirrored by `ExportI420Uniforms` in `ExportI420.swift`; every field 32 bits.
 22	struct ExportI420Uniforms {
 23	    uint width;
 24	    uint height;
 25	    uint lumaStride;
 26	    uint chromaStride;
 27	    uint cbOffset;
 28	    uint crOffset;
 29	};
 30	
 31	kernel void framejob_export_i420(texture2d<half, access::read> src [[texture(0)]],
 32	                                 device uchar *planes [[buffer(0)]],
 33	                                 constant ExportI420Uniforms &u [[buffer(1)]],
 34	                                 uint2 gid [[thread_position_in_grid]]) {
 35	    if (gid.x * 2 >= u.width || gid.y * 2 >= u.height) {
 36	        return;
 37	    }
 38	    const float3 weights = float3(0.2126, 0.7152, 0.0722);
 39	    float cb = 0.0;
 40	    float cr = 0.0;
 41	    float count = 0.0;
 42	    for (uint dy = 0; dy < 2; dy++) {
 43	        for (uint dx = 0; dx < 2; dx++) {
 44	            uint2 at = uint2(gid.x * 2 + dx, gid.y * 2 + dy);
 45	            if (at.x >= u.width || at.y >= u.height) {
 46	                continue;
 47	            }
 48	            float3 rgb = clamp(float3(src.read(at).rgb), 0.0, 1.0);
 49	            float luma = dot(rgb, weights);
 50	            planes[at.y * u.lumaStride + at.x] = uchar(round(16.0 + 219.0 * luma));
 51	            cb += (rgb.b - luma) / 1.8556;
 52	            cr += (rgb.r - luma) / 1.5748;
 53	            count += 1.0;
 54	        }
 55	    }
 56	    uint chroma = gid.y * u.chromaStride + gid.x;
 57	    planes[u.cbOffset + chroma] = uchar(clamp(round(128.0 + 224.0 * cb / count), 0.0, 255.0));
 58	    planes[u.crOffset + chroma] = uchar(clamp(round(128.0 + 224.0 * cr / count), 0.0, 255.0));
 59	}
  1	import AVFoundation
  2	
  3	/// The `av1` row's track in the MP4 (spec §11 CX-12 (4)): the `av01` format description
  4	/// holding the core's `av1C` record and the BT.709 video-range colour tags (the `colr`
  5	/// box), one sample per SVT-AV1 packet, and the written file's `ftyp` branded `av01`
  6	/// (AV1-ISOBMFF §2.1), which `AVAssetWriter` leaves out.
  7	enum ExportAV1Track {
  8	    /// `av01` at `width` × `height` with `config`'s record and BT.709 tags.
  9	    static func formatDescription(
 10	        width: Int, height: Int, config: ReelAV1.Config
 11	    ) throws -> CMVideoFormatDescription {
 12	        let extensions: [String: Any] = [
 13	            kCMFormatDescriptionExtension_SampleDescriptionExtensionAtoms as String: [
 14	                "av1C": config.record
 15	            ],
 16	            kCMFormatDescriptionExtension_ColorPrimaries as String:
 17	                kCMFormatDescriptionColorPrimaries_ITU_R_709_2,
 18	            kCMFormatDescriptionExtension_TransferFunction as String:
 19	                REDACTED,
 20	            kCMFormatDescriptionExtension_YCbCrMatrix as String:
 21	                REDACTED,
 22	            kCMFormatDescriptionExtension_FullRangeVideo as String: false,
 23	        ]
 24	        var description: CMVideoFormatDescription?
 25	        let status = CMVideoFormatDescriptionCreate(
 26	            allocator: kCFAllocatorDefault, codecType: kCMVideoCodecType_AV1,
 27	            width: Int32(clamping: width), height: Int32(clamping: height),
 28	            extensions: extensions as CFDictionary, formatDescriptionOut: &description)
 29	        guard status == noErr, let description else {
 30	            throw Exporter.ExportError.failed(
 31	                "The AV1 track could not be described (status \(status)).")
 32	        }
 33	        return description
 34	    }
 35	
 36	    /// One packet as one sample: presented at `at` for `duration`, no decode stamp (AV1
 37	    /// presents its temporal units in order). No sync attachment: the passthrough writer
 38	    /// marks the track's sync samples from the bitstream's own key frames (CX-12 (3)).
 39	    static func sample(
 40	        _ data: Data, at time: CMTime, duration: CMTime, format: CMVideoFormatDescription
 41	    ) -> CMSampleBuffer? {
 42	        var block: CMBlockBuffer?
 43	        guard CMBlockBufferCreateWithMemoryBlock(
 44	            allocator: kCFAllocatorDefault, memoryBlock: nil, blockLength: data.count,
 45	            blockAllocator: kCFAllocatorDefault, customBlockSource: nil, offsetToData: 0,
 46	            dataLength: data.count, flags: kCMBlockBufferAssureMemoryNowFlag,
 47	            blockBufferOut: &block) == kCMBlockBufferNoErr, let block
 48	        else { return nil }
 49	        let copied = data.withUnsafeBytes { bytes -> OSStatus in
 50	            guard let base = bytes.baseAddress else { return -1 }
 51	            return CMBlockBufferReplaceDataBytes(
 52	                with: base, blockBuffer: block, offsetIntoDestination: 0, dataLength: data.count)
 53	        }
 54	        guard copied == kCMBlockBufferNoErr else { return nil }
 55	        var timing = CMSampleTimingInfo(
 56	            duration: duration, presentationTimeStamp: time, decodeTimeStamp: .invalid)
 57	        var size = data.count
 58	        var sample: CMSampleBuffer?
 59	        guard CMSampleBufferCreateReady(
 60	            allocator: kCFAllocatorDefault, dataBuffer: block, formatDescription: format,
 61	            sampleCount: 1, sampleTimingEntryCount: 1, sampleTimingArray: &timing,
 62	            sampleSizeEntryCount: 1, sampleSizeArray: &size, sampleBufferOut: &sample) == noErr,
 63	            let sample
 64	        else { return nil }
 65	        return sample
 66	    }
 67	
 68	    /// Rewrites the finished file's `ftyp` to carry `av01`, in place (the core's
 69	    /// `rc_av1_ftyp_brand`: the first `mp41` becomes `av01`, no size or offset moves).
 70	    /// Throws when the file's first box cannot take it, which fails the export (CX-12 (4)).
 71	    static func brandFile(_ url: URL) throws {
 72	        let handle = try FileHandle(forUpdating: url)
 73	        defer { try? handle.close() }
 74	        var head = try handle.read(upToCount: 4096) ?? Data()
 75	        switch ReelAV1.brandAV01(&head) {
 76	        case 1:
 77	            try handle.seek(toOffset: 0)
 78	            try handle.write(contentsOf: head)
 79	        case 0:
 80	            return
 81	        default:
 82	            throw Exporter.ExportError.failed(
 83	                "The AV1 file's ftyp box could not be made to carry the av01 brand.")
 84	        }
 85	    }
 86	}
  1	#ifndef FRAMEJOB_BRIDGING_HEADER_H
  2	#define FRAMEJOB_BRIDGING_HEADER_H
  3	
  4	#include "../../core/include/framejob_core.h"
  5	
  6	// The bundled encoders (spec §11 CX-4): platform-side C APIs Swift calls
  7	// directly, never through an rc_* export. Their headers are build/codecs/include,
  8	// from tools/codecs/build_codecs.py (`make codecs`).
  9	#include <svt-av1/EbSvtAv1Enc.h>
